BEGIN;
-- Protected, fixed allowlist qualification facade. No importer authority or state mutation.
CREATE FUNCTION hr_performance_source_activation_qualification(t varchar,p varchar,actor uuid,draft uuid,revision uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
WITH selected AS MATERIALIZED (
 SELECT d.kind,d.current_revision_id,r.id revision_id,r.source_fact_id,r.snapshot,m.id manifest_id,m.migration_batch_id,m.manifest_sha256,m.content
 FROM public.hr_performance_source_draft d JOIN public.hr_performance_source_draft_revision r ON(r.id,r.tenant_id,r.park_id,r.draft_id)=(revision,t,p,d.id)
 JOIN public.hr_performance_source_manifest m ON(m.id,m.tenant_id,m.park_id)=(r.manifest_id,t,p)
 WHERE(d.id,d.tenant_id,d.park_id)=(draft,t,p) AND (public.hr_performance_channel_actor_has(t,p,actor,CASE d.kind WHEN 'template' THEN 'hr:performance_template:read' ELSE 'hr:performance:read' END) OR public.hr_performance_channel_actor_has(t,p,actor,CASE d.kind WHEN 'template' THEN 'hr:performance_template:manage' ELSE 'hr:performance:manage' END))
),generation AS MATERIALIZED(SELECT public.hr_performance_source_generation(t,p,s.kind,s.source_fact_id) g FROM selected s),owner AS MATERIALIZED(
 SELECT b.*,o.status operation_status,o.intent,o.execution_contract_version,o.sealed_plan_sha256 operation_plan,o.code_sha operation_code,o.source_snapshot_sha256 operation_source,o.mapping_contract_sha256 operation_mapping,o.target_identity_sha256 operation_target,o.target_scope_sha256 operation_scope,o.target_tenant_id,o.target_park_id,ph.status phase_status,ph.after_canonical_sha256
 FROM selected s JOIN public.migration_batch b ON b.id=s.migration_batch_id LEFT JOIN public.hr_yuzhou_production_import_operation o ON o.operation_id=b.production_import_operation_id LEFT JOIN public.hr_yuzhou_production_import_phase ph ON(ph.operation_id,ph.phase)=(o.operation_id,'T0')
),r308 AS MATERIALIZED(SELECT r.* FROM public.hr_yuzhou_performance_relations_production_receipt r JOIN owner o ON r.operation_id=o.production_import_operation_id),r310 AS MATERIALIZED(SELECT r.* FROM public.hr_yuzhou_performance_fact_identity_production_receipt r JOIN owner o ON r.operation_id=o.production_import_operation_id),r311 AS MATERIALIZED(SELECT r.* FROM public.hr_yuzhou_performance_facts_production_receipt r JOIN owner o ON r.operation_id=o.production_import_operation_id),r309 AS MATERIALIZED(SELECT r.* FROM public.hr_yuzhou_performance_person_assessment_operation r JOIN owner o ON(r.migration_batch_id,r.parent_import_operation_id)=(o.id,o.production_import_operation_id) WHERE(r.target_tenant_id,r.target_park_id)=(t,p)),
full_set AS MATERIALIZED(SELECT f.* FROM selected s CROSS JOIN LATERAL public.hr_yuzhou_performance_full_fact_set_v1(t,p,s.migration_batch_id) f),identity_set AS MATERIALIZED(SELECT f.* FROM selected s CROSS JOIN LATERAL public.hr_yuzhou_performance_fact_identity_set_v1(t,p,s.migration_batch_id) f),map_state AS MATERIALIZED(SELECT f.* FROM selected s CROSS JOIN LATERAL public.hr_yuzhou_performance_owner_map_state_v1(t,p,s.migration_batch_id) f),
master AS MATERIALIZED(SELECT f.* FROM public.hr_performance_legacy_master_result f JOIN selected s ON s.kind='review' AND(f.id,f.tenant_id,f.park_id)=(s.source_fact_id,t,p)),weight AS MATERIALIZED(SELECT r.* FROM public.hr_performance_legacy_ass_compute_weight_resolution r JOIN master m ON(r.legacy_master_result_id,r.tenant_id,r.park_id,r.migration_batch_id)=(m.id,t,p,m.migration_batch_id)),expected_weight AS MATERIALIZED(SELECT e.* FROM master m CROSS JOIN LATERAL public.hr_performance_yuzhou_ass_compute_weight_expectation(m.id) e),
profile AS MATERIALIZED(SELECT f.* FROM public.hr_performance_legacy_template_profile f JOIN selected s ON(f.tenant_id,f.park_id,f.migration_batch_id)=(t,p,s.migration_batch_id) WHERE(s.kind='template' AND f.id=s.source_fact_id) OR(s.kind='review' AND f.id=(SELECT person_template_profile_id FROM weight))),
result_facts AS MATERIALIZED(
 SELECT 'master_result'::text family,m.id,m.source_person_code,m.migration_batch_id FROM master m UNION ALL
 SELECT 'dimension_result',f.id,f.source_person_code,f.migration_batch_id FROM public.hr_performance_legacy_dimension_result f JOIN master m ON(f.tenant_id,f.park_id,f.migration_batch_id)=(t,p,m.migration_batch_id) AND f.source_session_id IS NOT DISTINCT FROM m.source_session_id AND f.source_person_code IS NOT DISTINCT FROM m.source_person_code
),t0_candidates AS MATERIALIZED(
 SELECT map.id map_id,map.source_identity_sha256,employee.id employee_id
 FROM public.legacy_record_map map JOIN public.hr_yuzhou_production_import_projection_receipt pr ON(pr.legacy_record_map_id,pr.phase)=(map.id,'T0')
 JOIN public.hr_yuzhou_production_import_record rec ON(rec.operation_id,rec.phase,rec.source_identity_sha256)=(pr.operation_id,pr.phase,pr.source_identity_sha256)
 JOIN public.hr_yuzhou_production_import_operation op ON op.operation_id=rec.operation_id JOIN public.hr_yuzhou_production_import_phase ph ON(ph.operation_id,ph.phase)=(op.operation_id,'T0')
 JOIN public.migration_batch b ON b.id=pr.migration_batch_id JOIN public.hr_employee employee ON(employee.id,employee.tenant_id,employee.park_id)=(map.target_id,t,p) AND NOT employee.is_deleted
 WHERE op.status='succeeded' AND op.intent='production_import' AND op.execution_contract_version=2 AND(op.target_tenant_id,op.target_park_id)=(t,p) AND ph.status='succeeded'
 AND(b.id,b.production_import_operation_id,b.source_system,b.execution_context,b.production_import_phase,b.status,b.target_database)=(map.batch_id,op.operation_id,'yuzhou-v10','production_import','T0','succeeded',current_database())
 AND map.source_system='yuzhou-v10' AND map.source_table='dbo.person' AND map.source_pk_canonical='sha256:'||map.source_identity_sha256 AND map.mapping_status='verified' AND map.is_active AND map.target_table='hr_employee'
 AND(rec.source_system,rec.source_table,rec.source_pk_canonical,rec.target_table,rec.target_id)=('yuzhou-v10','dbo.person',map.source_pk_canonical,'hr_employee',map.target_id) AND rec.disposition IN('insert','merge','skip_approved') AND rec.rollback_status='not_started'
),result_resolution AS MATERIALIZED(
 SELECT f.*,r.id resolution_id,r.person_resolution_status,r.source_person_identity_sha256,r.owner_t0_record_map_id,r.target_employee_id,
 (SELECT count(*) FROM t0_candidates c WHERE c.source_identity_sha256=public.hr_performance_yuzhou_person_identity_sha256(f.source_person_code)) candidate_count,
 (SELECT c.map_id FROM t0_candidates c WHERE c.source_identity_sha256=public.hr_performance_yuzhou_person_identity_sha256(f.source_person_code) LIMIT 1) candidate_map,
 (SELECT c.employee_id FROM t0_candidates c WHERE c.source_identity_sha256=public.hr_performance_yuzhou_person_identity_sha256(f.source_person_code) LIMIT 1) candidate_employee
 FROM result_facts f LEFT JOIN public.hr_performance_legacy_identity_resolution r ON(r.tenant_id,r.park_id,r.migration_batch_id,r.fact_kind,r.person_role)=(t,p,f.migration_batch_id,f.family,'subject') AND CASE f.family WHEN 'master_result' THEN r.legacy_master_result_id ELSE r.legacy_dimension_result_id END=f.id
),migration_claims AS(
 SELECT v.filename,v.checksum FROM r308 a,r310 b,r311 c CROSS JOIN LATERAL(VALUES
 ('000305_hr_performance_yuzhou_legacy_relations.sql',a.migration_305_sha256),('000306_hr_performance_yuzhou_identity_resolution.sql',a.migration_306_sha256),
 ('000308_hr_yuzhou_performance_relations_production.sql',b.migration_308_sha256),('000310_hr_yuzhou_performance_fact_identity_production.sql',b.migration_310_sha256),
 ('000300_hr_performance_yuzhou_legacy_model.sql',c.migration_300_sha256),('000301_hr_performance_yuzhou_legacy_writer.sql',c.migration_301_sha256),('000302_hr_performance_yuzhou_legacy_master.sql',c.migration_302_sha256),('000303_hr_performance_yuzhou_legacy_master_writer.sql',c.migration_303_sha256),('000310_hr_yuzhou_performance_fact_identity_production.sql',c.migration_310_sha256),('000311_hr_yuzhou_performance_facts_production.sql',c.migration_311_sha256))v(filename,checksum)
 UNION ALL SELECT '000307_hr_performance_yuzhou_ass_compute_weight_relation.sql',migration_307_sha256 FROM r309 UNION ALL SELECT '000308_hr_yuzhou_performance_relations_production.sql',migration_308_sha256 FROM r309
),gates AS MATERIALIZED(
 SELECT 'SOURCE_GENERATION'::text code,COALESCE((SELECT s.current_revision_id=revision AND g.g IS NOT NULL AND g.g->'content'=s.content AND g.g->>'manifestSha256'=s.manifest_sha256 FROM selected s,generation g),false) passed
 UNION ALL SELECT 'IMPORT_OWNER',COALESCE((SELECT o.operation_status='succeeded' AND o.intent='production_import' AND o.execution_contract_version=2 AND(o.target_tenant_id,o.target_park_id)=(t,p) AND o.phase_status='succeeded' AND o.status='succeeded' FROM owner o),false)
 UNION ALL SELECT 'RECEIPT_CHAIN',COALESCE((SELECT a.status='succeeded' AND b.status='succeeded' AND c.status='succeeded' AND a.rolled_back_at IS NULL AND b.rolled_back_at IS NULL AND c.rolled_back_at IS NULL AND a.rollback_operation_id IS NULL AND b.rollback_operation_id IS NULL AND c.rollback_operation_id IS NULL AND a.rollback_receipt_sha256 IS NULL AND b.rollback_receipt_sha256 IS NULL AND b.extension_rollback_nonce_sha256 IS NULL AND c.rollback_receipt_sha256 IS NULL
 AND ROW(a.migration_batch_id,a.sealed_plan_sha256,a.code_sha,a.source_snapshot_sha256,a.mapping_contract_sha256,a.target_identity_sha256,a.tenant_id,a.park_id,a.target_scope_sha256,a.t0_phase_receipt_sha256) IS NOT DISTINCT FROM ROW(o.id,o.operation_plan,o.operation_code,o.operation_source,o.operation_mapping,o.operation_target,t,p,o.operation_scope,o.after_canonical_sha256)
 AND ROW(c.migration_batch_id,c.sealed_plan_sha256,c.code_sha,c.source_snapshot_sha256,c.mapping_contract_sha256,c.target_identity_sha256,c.tenant_id,c.park_id,c.target_scope_sha256,c.t0_phase_receipt_sha256) IS NOT DISTINCT FROM ROW(a.migration_batch_id,a.sealed_plan_sha256,a.code_sha,a.source_snapshot_sha256,a.mapping_contract_sha256,a.target_identity_sha256,a.tenant_id,a.park_id,a.target_scope_sha256,a.t0_phase_receipt_sha256)
 AND ROW(b.migration_batch_id,b.sealed_plan_sha256,b.code_sha,b.source_snapshot_sha256,b.mapping_contract_sha256,b.target_identity_sha256,b.tenant_id,b.park_id,b.target_scope_sha256,b.t0_phase_receipt_sha256) IS NOT DISTINCT FROM ROW(a.migration_batch_id,a.sealed_plan_sha256,a.code_sha,a.source_snapshot_sha256,a.mapping_contract_sha256,a.target_identity_sha256,a.tenant_id,a.park_id,a.target_scope_sha256,a.t0_phase_receipt_sha256)
 AND(b.parent_relations_receipt_sha256,b.fact_loader_receipt_sha256,b.fact_set_sha256,b.dimension_rows,b.master_rows) IS NOT DISTINCT FROM(a.receipt_sha256,c.receipt_sha256,c.identity_fact_set_sha256,c.dimension_result_rows,c.master_result_rows) FROM r308 a,r310 b,r311 c,owner o),false)
 UNION ALL SELECT 'MIGRATION_CHECKSUMS',EXISTS(SELECT 1 FROM migration_claims) AND NOT EXISTS(SELECT 1 FROM migration_claims c WHERE NOT EXISTS(SELECT 1 FROM public.schema_migrations m JOIN public.sys_schema_migration_history h USING(filename,checksum,status) WHERE(m.filename,m.checksum,m.status)=(c.filename,c.checksum,'succeeded')))
 UNION ALL SELECT 'FULL_FACT_CONSERVATION',COALESCE((SELECT ROW(f.template_rows,f.level_rule_rows,f.dimension_rows,f.guide_rows,f.dimension_result_rows,f.master_result_rows,f.active_fact_maps,f.full_fact_set_sha256) IS NOT DISTINCT FROM ROW(c.template_rows,c.level_rule_rows,c.dimension_rows,c.guide_rows,c.dimension_result_rows,c.master_result_rows,c.active_fact_maps,c.full_fact_set_sha256) AND ROW(i.dimension_rows,i.master_rows,i.fact_rows,i.fact_set_sha256) IS NOT DISTINCT FROM ROW(b.dimension_rows,b.master_rows,b.fact_rows,b.fact_set_sha256) AND public.hr_yuzhou_performance_fact_identity_state_v1(t,p,s.migration_batch_id) IS NOT DISTINCT FROM b.resolution_state_sha256 FROM full_set f,identity_set i,r310 b,r311 c,selected s),false)
 UNION ALL SELECT 'OWNER_MAP_CONSERVATION',COALESCE((SELECT ROW(m.fact_owner_maps,m.relation_owner_maps,m.verified_owner_maps,m.owner_map_state_sha256) IS NOT DISTINCT FROM ROW(b.fact_owner_maps,b.relation_owner_maps,b.verified_owner_maps,b.owner_map_state_sha256) AND m.invalid_owner_maps=0 AND m.loaded_owner_maps=0 AND m.owner_maps=m.distinct_owner_maps AND m.owner_maps=m.active_target_maps AND m.owner_maps=m.verified_owner_maps FROM map_state m,r310 b),false)
 UNION ALL SELECT 'IMPORT_ITEM_DISCREPANCY',NOT EXISTS(SELECT 1 FROM public.migration_batch_item i JOIN selected s ON i.batch_id=s.migration_batch_id WHERE i.source_object IN('dbo.assessmentcode','dbo.assgradecode','dbo.assitem','dbo.assitemgradedes','dbo.assessmentdetail','dbo.assessmentmaster') AND i.phase IN('load','verify') AND i.status IN('failed','quarantined'))
 UNION ALL SELECT 'PERSON_ASSESSMENT_OPERATION',s.kind='template' OR COALESCE((SELECT o.status='succeeded' AND o.started_at IS NOT NULL AND o.finished_at IS NOT NULL AND o.rolled_back_at IS NULL AND(o.code_sha,o.source_snapshot_sha256,o.mapping_contract_sha256,o.target_identity_sha256,o.target_scope_sha256,o.t0_artifact_sha256) IS NOT DISTINCT FROM (a.code_sha,a.source_snapshot_sha256,a.mapping_contract_sha256,a.target_identity_sha256,a.target_scope_sha256,a.t0_phase_receipt_sha256) AND public.hr_yuzhou_performance_person_assessment_owner_state_sha256(s.migration_batch_id) IS NOT DISTINCT FROM o.owner_state_sha256 AND public.hr_yuzhou_performance_person_assessment_state_sha256(s.migration_batch_id,'succeeded',o.binding_sha256) IS NOT DISTINCT FROM o.applied_state_sha256 AND o.applied_evidence_rows=(SELECT count(*) FROM public.hr_performance_legacy_person_assessment_evidence e WHERE(e.migration_batch_id,e.tenant_id,e.park_id)=(s.migration_batch_id,t,p)) AND o.applied_master_rows=(SELECT count(*) FROM public.hr_performance_legacy_master_result m WHERE(m.migration_batch_id,m.tenant_id,m.park_id)=(s.migration_batch_id,t,p)) AND o.applied_resolution_rows=(SELECT count(*) FROM public.hr_performance_legacy_ass_compute_weight_resolution r WHERE(r.migration_batch_id,r.tenant_id,r.park_id)=(s.migration_batch_id,t,p)) FROM r309 o,r308 a),false) FROM selected s
 UNION ALL SELECT 'PROFILE_RESOLUTION',s.kind='template' OR COALESCE((SELECT w.person_resolution_status='resolved' AND w.source_person_evidence_count=1 AND w.person_template_candidate_count=1 AND w.detail_resolution_status='resolved' AND w.detail_template_candidate_count=1 AND w.comparison_status='matched' AND w.person_template_profile_id IS NOT NULL AND w.person_template_profile_id=w.detail_template_profile_id
 AND ROW(w.source_person_identity_sha256,w.source_person_evidence_count,w.source_person_assessment_id,w.person_template_candidate_count,w.person_template_profile_id,w.person_resolution_status,w.detail_template_candidate_count,w.detail_template_profile_id,w.detail_resolution_status,w.comparison_status) IS NOT DISTINCT FROM ROW(e.source_person_identity_sha256,e.source_person_evidence_count,e.source_person_assessment_id,e.person_template_candidate_count,e.person_template_profile_id,e.person_resolution_status,e.detail_template_candidate_count,e.detail_template_profile_id,e.detail_resolution_status,e.comparison_status)
 AND w.evidence_sha256 IS NOT DISTINCT FROM public.hr_performance_yuzhou_ass_compute_weight_evidence_sha256(w.legacy_master_result_id,w.source_person_identity_sha256,w.source_person_evidence_count,w.source_person_assessment_id,w.person_template_candidate_count,w.person_template_profile_id,w.person_resolution_status,w.detail_template_candidate_count,w.detail_template_profile_id,w.detail_resolution_status,w.comparison_status)
 AND (SELECT count(*) FROM public.hr_performance_legacy_person_assessment_evidence pe JOIN profile pr ON pe.source_assessment_id=pr.source_assessment WHERE(pe.migration_batch_id,pe.tenant_id,pe.park_id,pe.source_person_identity_sha256)=(s.migration_batch_id,t,p,w.source_person_identity_sha256) AND pe.evidence_sha256 IS NOT DISTINCT FROM public.hr_performance_yuzhou_person_assessment_evidence_sha256(pe.source_person_identity_sha256,pe.source_assessment_id))=1 FROM weight w,expected_weight e),false) FROM selected s
 UNION ALL SELECT 'RESULT_SUBJECT_IDENTITY',s.kind='template' OR (EXISTS(SELECT 1 FROM result_facts WHERE family='dimension_result') AND NOT EXISTS(SELECT 1 FROM result_resolution r WHERE r.resolution_id IS NULL OR r.person_resolution_status IS DISTINCT FROM 'resolved' OR r.source_person_identity_sha256 IS DISTINCT FROM public.hr_performance_yuzhou_person_identity_sha256(r.source_person_code) OR r.candidate_count<>1 OR r.owner_t0_record_map_id IS DISTINCT FROM r.candidate_map OR r.target_employee_id IS DISTINCT FROM r.candidate_employee OR r.target_employee_id IS DISTINCT FROM (SELECT target_employee_id FROM result_resolution WHERE family='master_result'))) FROM selected s
 UNION ALL SELECT 'PROFILE_CATALOG',EXISTS(SELECT 1 FROM profile)
),result AS(
 SELECT jsonb_build_object('sourceQualified',(SELECT bool_and(passed) FROM gates),'qualificationGateCodes',COALESCE((SELECT jsonb_agg(code ORDER BY code COLLATE "C") FROM gates WHERE NOT passed),'[]'::jsonb),'manifestSha256',s.manifest_sha256,'profileIdentitySha256',(SELECT source_identity_sha256 FROM profile),'resolvedEmployeeId',CASE WHEN s.kind='review' THEN (SELECT target_employee_id FROM result_resolution WHERE family='master_result') END,'qualificationCounts',jsonb_build_object('selectedDetails',(SELECT count(*) FROM result_facts WHERE family='dimension_result'),'factRows',(SELECT fact_rows FROM identity_set),'unresolvedSubjects',(SELECT unmatched_rows+ambiguous_rows+not_applicable_rows FROM r310)),'gates',(SELECT jsonb_object_agg(code,passed ORDER BY code COLLATE "C") FROM gates),
 'qualificationHash',encode(sha256(convert_to(jsonb_build_object('contract','formal-activation-v1','manifestSha256',s.manifest_sha256,'receipt308Sha256',(SELECT receipt_sha256 FROM r308),'receipt310Sha256',(SELECT receipt_sha256 FROM r310),'receipt311Sha256',(SELECT receipt_sha256 FROM r311),'operation309Id',CASE WHEN s.kind='review' THEN (SELECT operation_id FROM r309) END,'operation309StateSha256',CASE WHEN s.kind='review' THEN (SELECT applied_state_sha256 FROM r309) END,'profileIdentitySha256',(SELECT source_identity_sha256 FROM profile),'employeeId',CASE WHEN s.kind='review' THEN (SELECT target_employee_id FROM result_resolution WHERE family='master_result') END,'gates',(SELECT jsonb_object_agg(code,passed ORDER BY code COLLATE "C") FROM gates))::text,'UTF8')),'hex')) value FROM selected s
) SELECT value FROM result
$$;
REVOKE ALL ON FUNCTION hr_performance_source_activation_qualification(varchar,varchar,uuid,uuid,uuid) FROM PUBLIC;
CREATE FUNCTION hr_performance_source_activation_mapping(t varchar,p varchar,draft uuid,revision uuid,profile_identity text,manual boolean DEFAULT false)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $$
WITH source AS(SELECT r.source_fact_id,r.snapshot,m.migration_batch_id FROM public.hr_performance_source_draft d JOIN public.hr_performance_source_draft_revision r ON(r.id,r.tenant_id,r.park_id,r.draft_id)=(revision,t,p,d.id) JOIN public.hr_performance_source_manifest m ON m.id=r.manifest_id WHERE(d.id,d.tenant_id,d.park_id)=(draft,t,p)),
profile AS(SELECT f.* FROM public.hr_performance_legacy_template_profile f JOIN source s ON(f.tenant_id,f.park_id,f.migration_batch_id)=(t,p,s.migration_batch_id) WHERE f.source_identity_sha256=profile_identity AND NOT manual),
items AS(SELECT f.* FROM public.hr_performance_legacy_dimension_profile f JOIN profile a ON(f.legacy_template_profile_id,f.tenant_id,f.park_id,f.migration_batch_id)=(a.id,t,p,a.migration_batch_id) AND f.source_assessment_id=a.source_assessment),
grades AS(SELECT f.* FROM public.hr_performance_legacy_level_rule f JOIN profile a ON(f.legacy_template_profile_id,f.tenant_id,f.park_id,f.migration_batch_id)=(a.id,t,p,a.migration_batch_id) AND f.source_assessment_id=a.source_assessment),
guides AS(SELECT f.*,i.source_identity_sha256 item_identity FROM public.hr_performance_legacy_dimension_level_guide f JOIN items i ON(f.legacy_dimension_profile_id,f.tenant_id,f.park_id,f.migration_batch_id)=(i.id,t,p,i.migration_batch_id) AND f.source_item_id=i.source_item_id),
master AS(SELECT m.* FROM public.hr_performance_legacy_master_result m JOIN source s ON(m.id,m.tenant_id,m.park_id,m.migration_batch_id)=(s.source_fact_id,t,p,s.migration_batch_id)),
details AS(SELECT f.*,i.source_identity_sha256 item_identity FROM public.hr_performance_legacy_dimension_result f JOIN master m ON(f.tenant_id,f.park_id,f.migration_batch_id)=(t,p,m.migration_batch_id) AND f.source_session_id IS NOT DISTINCT FROM m.source_session_id AND f.source_person_code IS NOT DISTINCT FROM m.source_person_code JOIN items i ON(f.legacy_dimension_profile_id,f.source_item_id)=(i.id,i.source_item_id))
SELECT jsonb_build_object('profileIdentitySha256',CASE WHEN manual THEN NULL ELSE profile_identity END,'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('sourceIdentitySha256',source_identity_sha256,'itemId','item:'||source_identity_sha256) ORDER BY source_identity_sha256 COLLATE "C") FROM items),'[]'::jsonb),'grades',COALESCE((SELECT jsonb_agg(jsonb_build_object('sourceIdentitySha256',source_identity_sha256,'gradeId','grade:'||source_identity_sha256) ORDER BY source_identity_sha256 COLLATE "C") FROM grades),'[]'::jsonb),'guides',COALESCE((SELECT jsonb_agg(jsonb_build_object('sourceIdentitySha256',source_identity_sha256,'itemId','item:'||item_identity,'guideId','guide:'||source_identity_sha256) ORDER BY source_identity_sha256 COLLATE "C") FROM guides),'[]'::jsonb),'details',COALESCE((SELECT jsonb_agg(jsonb_build_object('sourceIdentitySha256',source_identity_sha256,'detailId','detail:'||source_identity_sha256,'itemId','item:'||item_identity) ORDER BY source_identity_sha256 COLLATE "C") FROM details),'[]'::jsonb))
WHERE manual OR (EXISTS(SELECT 1 FROM profile) AND (SELECT count(*) FROM details)=(SELECT count(*) FROM public.hr_performance_legacy_dimension_result f JOIN master m ON(f.tenant_id,f.park_id,f.migration_batch_id)=(t,p,m.migration_batch_id) AND f.source_session_id IS NOT DISTINCT FROM m.source_session_id AND f.source_person_code IS NOT DISTINCT FROM m.source_person_code))
$$;
CREATE FUNCTION hr_performance_source_activation_cell(v jsonb,actor uuid,at timestamptz,evidence text) RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
SELECT CASE WHEN v IS NULL OR v='null'::jsonb THEN '{"state":"UNPROVIDED","value":null,"actorUserId":null,"changedAt":null,"evidence":null}'::jsonb ELSE jsonb_build_object('state','VALUE','value',v,'actorUserId',actor,'changedAt',at,'evidence',evidence) END
$$;

CREATE TABLE hr_performance_source_activation_receipt(
 id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id varchar(64) NOT NULL,park_id varchar(64) NOT NULL,kind text NOT NULL CHECK(kind IN('template','review')),mode text NOT NULL CHECK(mode IN('template_draft','qualified_source','manual_current')),
 draft_id uuid NOT NULL,draft_revision_id uuid NOT NULL,manifest_id uuid NOT NULL,source_fact_id uuid NOT NULL,source_identity_sha256 char(64) NOT NULL,predecessor_receipt_id uuid,
 business_key_sha256 char(64) NOT NULL CHECK(business_key_sha256~'^[0-9a-f]{64}$'),request_sha256 char(64) NOT NULL CHECK(request_sha256~'^[0-9a-f]{64}$'),request jsonb NOT NULL,
 qualification jsonb NOT NULL,qualification_sha256 char(64) NOT NULL,mapping jsonb NOT NULL,binding jsonb NOT NULL,definition_difference jsonb NOT NULL,pending_input_difference jsonb NOT NULL,
 template_id uuid NOT NULL,template_version_id uuid NOT NULL,definition_revision_id uuid NOT NULL,workflow_revision_id uuid,cycle_id uuid,review_id uuid,employee_id uuid,initial_revision_id uuid,baseline_revision_id uuid,
 reason varchar(2000) NOT NULL CHECK(length(btrim(reason)) BETWEEN 2 AND 2000),created_by uuid NOT NULL REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),created_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),
 UNIQUE(id,tenant_id,park_id),UNIQUE(tenant_id,park_id,business_key_sha256),UNIQUE(template_version_id,tenant_id,park_id),UNIQUE(cycle_id,tenant_id,park_id),UNIQUE(review_id,tenant_id,park_id),UNIQUE(baseline_revision_id,tenant_id,park_id),
 CHECK(predecessor_receipt_id IS NULL),CHECK((kind='template' AND mode='template_draft' AND cycle_id IS NULL AND review_id IS NULL AND employee_id IS NULL AND initial_revision_id IS NULL AND baseline_revision_id IS NULL) OR(kind='review' AND mode IN('qualified_source','manual_current') AND cycle_id IS NOT NULL AND review_id IS NOT NULL AND employee_id IS NOT NULL AND initial_revision_id IS NOT NULL AND workflow_revision_id IS NOT NULL AND((mode='qualified_source' AND baseline_revision_id IS NOT NULL) OR(mode='manual_current' AND baseline_revision_id IS NULL)))),
 FOREIGN KEY(draft_id,tenant_id,park_id) REFERENCES hr_performance_source_draft(id,tenant_id,park_id),
 FOREIGN KEY(draft_revision_id,tenant_id,park_id,draft_id) REFERENCES hr_performance_source_draft_revision(id,tenant_id,park_id,draft_id),
 FOREIGN KEY(manifest_id,tenant_id,park_id) REFERENCES hr_performance_source_manifest(id,tenant_id,park_id),
 FOREIGN KEY(predecessor_receipt_id,tenant_id,park_id) REFERENCES hr_performance_source_activation_receipt(id,tenant_id,park_id),
 FOREIGN KEY(template_id,tenant_id,park_id) REFERENCES hr_performance_template(id,tenant_id,park_id) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(template_version_id,tenant_id,park_id) REFERENCES hr_performance_template_version(id,tenant_id,park_id) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(definition_revision_id,tenant_id,park_id,template_version_id) REFERENCES hr_performance_channel_definition_revision(id,tenant_id,park_id,template_version_id) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(workflow_revision_id,tenant_id,park_id,template_version_id) REFERENCES hr_performance_channel_workflow_revision(id,tenant_id,park_id,template_version_id) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(cycle_id,tenant_id,park_id) REFERENCES hr_performance_review_cycle(id,tenant_id,park_id) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(review_id,tenant_id,park_id) REFERENCES hr_performance_cycle_employee(id,tenant_id,park_id) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(initial_revision_id,tenant_id,park_id,review_id) REFERENCES hr_performance_channel_input_revision(id,tenant_id,park_id,cycle_employee_id) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(baseline_revision_id,tenant_id,park_id,review_id) REFERENCES hr_performance_channel_input_revision(id,tenant_id,park_id,cycle_employee_id) DEFERRABLE INITIALLY DEFERRED
);
ALTER TABLE hr_performance_review_cycle ADD COLUMN source_activation_receipt_id uuid,ADD FOREIGN KEY(source_activation_receipt_id,tenant_id,park_id) REFERENCES hr_performance_source_activation_receipt(id,tenant_id,park_id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE hr_performance_channel_input_revision ADD COLUMN source_activation_receipt_id uuid,ADD FOREIGN KEY(source_activation_receipt_id,tenant_id,park_id) REFERENCES hr_performance_source_activation_receipt(id,tenant_id,park_id) DEFERRABLE INITIALLY DEFERRED;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM hr_performance_cycle_employee WHERE predecessor_review_id IS NOT NULL GROUP BY tenant_id,park_id,predecessor_review_id HAVING count(*)>1) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_DUPLICATE_CORRECTION_PREDECESSOR';END IF;END $$;
CREATE UNIQUE INDEX uq_hr_performance_confirmed_correction_predecessor ON hr_performance_cycle_employee(tenant_id,park_id,predecessor_review_id) WHERE predecessor_review_id IS NOT NULL;
CREATE FUNCTION hr_performance_source_activation_build_input(content jsonb,workflow jsonb,mapping jsonb,master_id uuid,actor uuid,at timestamptz,rid uuid)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $$
WITH facts AS(SELECT f FROM jsonb_array_elements(content->'facts') f),master AS(SELECT f FROM facts WHERE f->>'family'='master_result' AND f->>'sourceFactId'=master_id::text),details AS(
 SELECT m.value map,f.f FROM jsonb_array_elements(mapping->'details') m JOIN facts f ON f.f->>'family'='dimension_result' AND f.f->>'identitySha256'=m.value->>'sourceIdentitySha256'
),detail_inputs AS(
 SELECT map->>'sourceIdentitySha256' identity,jsonb_build_object('id',map->'detailId','itemId',map->'itemId','channels',(SELECT jsonb_object_agg(c.field,public.hr_performance_source_activation_cell(f->'values'->c.source,actor,at,'source-activation:'||rid||':dimension_result:'||(map->>'sourceIdentitySha256')||':'||c.field)) FROM(VALUES('s','source_self_value'),('m','source_m_item_value'),('t','source_item_value'),('x','source_x_item_value'),('c','source_c_item_value'))c(field,source))) || CASE WHEN workflow ? 'detailAppraisalPolicy' THEN jsonb_build_object('appraisal',public.hr_performance_source_activation_cell(f->'values'->'source_appraisal',actor,at,'source-activation:'||rid||':dimension_result:'||(map->>'sourceIdentitySha256')||':detailAppraisal')) ELSE '{}'::jsonb END value FROM details
)
SELECT jsonb_build_object('schemaVersion',1,'details',COALESCE((SELECT jsonb_agg(value ORDER BY identity COLLATE "C") FROM detail_inputs),'[]'::jsonb),'adjustments',(SELECT jsonb_object_agg(c.field,public.hr_performance_source_activation_cell((SELECT f->'values'->c.source FROM master),actor,at,'source-activation:'||rid||':master_result:'||COALESCE((SELECT f->>'identitySha256' FROM master),'')||':'||c.field)) FROM(VALUES('master','source_master_value'),('timekeep','source_timekeep_value'),('bonus','source_bonus_value'))c(field,source)),'master',(SELECT jsonb_object_agg(c.field,public.hr_performance_source_activation_cell((SELECT f->'values'->c.source FROM master),actor,at,'source-activation:'||rid||':master_result:'||COALESCE((SELECT f->>'identitySha256' FROM master),'')||':'||c.field)) FROM(VALUES('selfAppraisal','source_self_appraisal'),('appraisal','source_appraisal'),('description','source_description'),('salaryReference','source_pay'))c(field,source)))
$$;
CREATE FUNCTION hr_performance_source_activation_expected_input(receipt_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $$
 SELECT public.hr_performance_source_activation_build_input(m.content,d.snapshot->'workflow',r.mapping,r.source_fact_id,r.created_by,r.created_at,r.id) FROM public.hr_performance_source_activation_receipt r JOIN public.hr_performance_source_manifest m ON m.id=r.manifest_id JOIN public.hr_performance_source_draft_revision d ON d.id=r.draft_revision_id WHERE r.id=receipt_id AND r.mode='qualified_source'
$$;
CREATE FUNCTION hr_performance_source_activation_mapping_config_valid(mapping jsonb,definition jsonb,workflow jsonb,qualified boolean) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE item jsonb;guide jsonb;grade jsonb;actual jsonb;
BEGIN
 IF NOT public.hr_performance_channel_config_valid_v1(definition) OR(workflow IS NOT NULL AND workflow<>'null'::jsonb AND NOT public.hr_performance_channel_workflow_valid(workflow,definition,qualified)) THEN RETURN false;END IF;
 IF qualified AND(workflow IS NULL OR workflow='null'::jsonb) THEN RETURN false;END IF;
 IF mapping->'profileIdentitySha256'='null'::jsonb THEN RETURN NOT qualified;END IF;
 IF jsonb_array_length(mapping->'items')<>jsonb_array_length(definition->'items') OR jsonb_array_length(mapping->'grades')<>jsonb_array_length(definition->'gradeCandidates') THEN RETURN false;END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(mapping->'items') LOOP
 SELECT value INTO actual FROM jsonb_array_elements(definition->'items') WHERE value->'id'=item->'itemId';IF actual IS NULL OR jsonb_array_length(actual->'guides')<>(SELECT count(*) FROM jsonb_array_elements(mapping->'guides') g WHERE g->'itemId'=item->'itemId') THEN RETURN false;END IF;
 FOR guide IN SELECT value FROM jsonb_array_elements(mapping->'guides') WHERE value->'itemId'=item->'itemId' LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual->'guides') a WHERE a->'id'=guide->'guideId') THEN RETURN false;END IF;END LOOP;
 END LOOP;
 FOR grade IN SELECT value FROM jsonb_array_elements(mapping->'grades') LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(definition->'gradeCandidates') a WHERE a->'id'=grade->'gradeId') THEN RETURN false;END IF;END LOOP;
 IF qualified AND(jsonb_array_length(mapping->'details')=0 OR(SELECT jsonb_agg(jsonb_build_object('id',a->'detailId','itemId',a->'itemId') ORDER BY a->>'detailId' COLLATE "C") FROM jsonb_array_elements(mapping->'details') a) IS DISTINCT FROM(SELECT jsonb_agg(a ORDER BY a->>'id' COLLATE "C") FROM jsonb_array_elements(workflow->'detailDefinitions') a)) THEN RETURN false;END IF;RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION hr_performance_channel_cycle_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v record;d jsonb;w record;source_r public.hr_performance_source_activation_receipt%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' AND NEW.source_activation_receipt_id IS DISTINCT FROM OLD.source_activation_receipt_id THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_CYCLE_LINK_IMMUTABLE';END IF;
 IF NEW.source_activation_receipt_id IS NOT NULL THEN
 SELECT * INTO source_r FROM public.hr_performance_source_activation_receipt WHERE(id,tenant_id,park_id)=(NEW.source_activation_receipt_id,NEW.tenant_id,NEW.park_id);
 IF source_r.id IS NULL OR source_r.kind<>'review' OR source_r.cycle_id<>NEW.id OR source_r.template_version_id<>NEW.template_version_id OR NEW.cycle_code IS DISTINCT FROM source_r.request->>'cycleCode' OR NEW.cycle_name IS DISTINCT FROM source_r.request->>'cycleName' OR NEW.selected_employee_ids IS DISTINCT FROM jsonb_build_array(source_r.employee_id) OR NEW.applicable_org_ids IS DISTINCT FROM jsonb_build_array(source_r.binding->>'orgId') OR NEW.business_period_ref IS DISTINCT FROM source_r.binding->>'businessPeriodRef' OR NEW.start_date IS DISTINCT FROM(source_r.binding->>'startDate')::date OR NEW.end_date IS DISTINCT FROM(source_r.binding->>'endDate')::date OR NEW.correction_reason IS NOT NULL OR NEW.predecessor_review_ids IS NOT NULL OR NEW.create_by IS DISTINCT FROM source_r.created_by OR NEW.create_time IS DISTINCT FROM source_r.created_at OR(TG_OP='INSERT' AND source_r.created_xid IS DISTINCT FROM pg_current_xact_id()) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_CYCLE_INVALID';END IF;
 END IF;
 SELECT * INTO v FROM hr_performance_template_version WHERE(id,tenant_id,park_id)=(NEW.template_version_id,NEW.tenant_id,NEW.park_id) FOR SHARE;
 IF v.calculation_mode='five_channel_v1' THEN
  IF TG_OP='INSERT' AND(NEW.status<>'planning' OR NEW.published_at IS NOT NULL) THEN RAISE EXCEPTION 'channel cycle must start in unpublished planning';END IF;
  SELECT config INTO d FROM hr_performance_channel_definition_revision WHERE id=v.channel_definition_revision_id;
  SELECT * INTO w FROM hr_performance_channel_workflow_revision WHERE id=v.channel_workflow_revision_id;
  IF v.status<>'published' OR NOT hr_performance_channel_workflow_valid(w.policy,d,true) OR NEW.template_snapshot->>'calculationMode' IS DISTINCT FROM 'five_channel_v1' OR NEW.template_snapshot->>'currentRevisionId' IS DISTINCT FROM v.channel_definition_revision_id::text OR NEW.template_snapshot->>'workflowRevisionId' IS DISTINCT FROM v.channel_workflow_revision_id::text OR NEW.template_snapshot->'channelDefinition' IS DISTINCT FROM d OR NEW.template_snapshot->'channelWorkflow' IS DISTINCT FROM w.policy THEN RAISE EXCEPTION 'channel cycle must freeze exact published revisions';END IF;
 ELSIF NEW.template_snapshot ? 'calculationMode' AND NEW.template_snapshot->>'calculationMode' IS DISTINCT FROM 'dimension_weighted_v1' THEN RAISE EXCEPTION 'invalid frozen mode';END IF;
 IF v.calculation_mode='five_channel_v1' AND TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
  IF NOT EXISTS(SELECT 1 FROM hr_performance_cycle_employee e WHERE(e.cycle_id,e.tenant_id,e.park_id)=(NEW.id,NEW.tenant_id,NEW.park_id)) OR EXISTS(SELECT 1 FROM hr_performance_cycle_employee e WHERE(e.cycle_id,e.tenant_id,e.park_id)=(NEW.id,NEW.tenant_id,NEW.park_id) AND ((NEW.status='manager_review' AND e.status='self_review') OR(NEW.status='calibration' AND e.status IN('self_review','manager_review')) OR(NEW.status='employee_acknowledged' AND e.status IN('self_review','manager_review','calibration')) OR(NEW.status='confirmed' AND e.status<>'confirmed'))) THEN RAISE EXCEPTION 'channel cycle stage requires employee evidence';END IF;
 END IF;
 IF TG_OP='UPDATE' AND(NEW.correction_reason,NEW.business_period_ref,NEW.selected_employee_ids,NEW.predecessor_review_ids) IS DISTINCT FROM(OLD.correction_reason,OLD.business_period_ref,OLD.selected_employee_ids,OLD.predecessor_review_ids) THEN RAISE EXCEPTION 'correction identity is immutable';END IF;
 IF NEW.predecessor_review_ids IS NOT NULL THEN
  IF jsonb_typeof(NEW.predecessor_review_ids)<>'array' OR jsonb_typeof(NEW.selected_employee_ids) IS DISTINCT FROM 'array' OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(NEW.predecessor_review_ids))<>jsonb_array_length(NEW.predecessor_review_ids) OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(NEW.selected_employee_ids))<>jsonb_array_length(NEW.selected_employee_ids) OR jsonb_array_length(NEW.predecessor_review_ids)=0 OR jsonb_array_length(NEW.predecessor_review_ids)<>jsonb_array_length(NEW.selected_employee_ids) OR NEW.correction_reason IS NULL OR length(btrim(NEW.correction_reason))<2 OR NEW.business_period_ref IS NULL OR length(btrim(NEW.business_period_ref))=0 THEN RAISE EXCEPTION 'explicit correction identity required';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.predecessor_review_ids) ids(id) WHERE NOT EXISTS(SELECT 1 FROM hr_performance_cycle_employee ce WHERE(ce.id,ce.tenant_id,ce.park_id)=(ids.id::uuid,NEW.tenant_id,NEW.park_id) AND ce.status='confirmed' AND NEW.selected_employee_ids ? ce.employee_id::text)) THEN RAISE EXCEPTION 'confirmed correction predecessor required';END IF;
 ELSIF NEW.source_activation_receipt_id IS NULL AND(NEW.selected_employee_ids IS NOT NULL OR NEW.correction_reason IS NOT NULL OR NEW.business_period_ref IS NOT NULL) THEN RAISE EXCEPTION 'incomplete correction identity';END IF;RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION hr_performance_channel_employee_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c record;r record;source_r public.hr_performance_source_activation_receipt%ROWTYPE;
BEGIN
 SELECT * INTO c FROM hr_performance_review_cycle WHERE(id,tenant_id,park_id)=(NEW.cycle_id,NEW.tenant_id,NEW.park_id) FOR SHARE;
 IF c.source_activation_receipt_id IS NOT NULL THEN
 SELECT * INTO source_r FROM public.hr_performance_source_activation_receipt WHERE(id,tenant_id,park_id)=(c.source_activation_receipt_id,NEW.tenant_id,NEW.park_id);
 IF source_r.id IS NULL OR source_r.review_id<>NEW.id OR source_r.employee_id<>NEW.employee_id OR NEW.predecessor_review_id IS NOT NULL OR(TG_OP='INSERT' AND source_r.created_xid IS DISTINCT FROM pg_current_xact_id()) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_COHORT_INVALID';END IF;
 END IF;
 IF NEW.calculation_mode IS DISTINCT FROM COALESCE(c.template_snapshot->>'calculationMode','dimension_weighted_v1') THEN RAISE EXCEPTION 'employee mode must match frozen cycle';END IF;
 IF TG_OP='INSERT' AND NEW.calculation_mode='five_channel_v1' AND(NEW.status NOT IN('planning','self_review') OR num_nonnulls(NEW.self_score,NEW.manager_score,NEW.calibrated_score,NEW.final_score,NEW.final_level_code,NEW.final_level_name,NEW.result_finalized_at,NEW.acknowledged_at,NEW.confirmed_at,NEW.current_input_revision_id,NEW.final_input_revision_id,NEW.final_grade_evidence)>0) THEN RAISE EXCEPTION 'channel employee must start without score or result evidence';END IF;
 IF TG_OP='INSERT' AND c.source_activation_receipt_id IS NULL AND c.selected_employee_ids IS NOT NULL AND (NOT c.selected_employee_ids ? NEW.employee_id::text OR NEW.predecessor_review_id IS NULL OR NOT c.predecessor_review_ids ? NEW.predecessor_review_id::text OR NOT EXISTS(SELECT 1 FROM hr_performance_cycle_employee p WHERE(p.id,p.tenant_id,p.park_id,p.employee_id)=(NEW.predecessor_review_id,NEW.tenant_id,NEW.park_id,NEW.employee_id) AND p.status='confirmed')) THEN RAISE EXCEPTION 'employee is outside explicit correction selection';END IF;
 IF c.selected_employee_ids IS NULL AND NEW.predecessor_review_id IS NOT NULL THEN RAISE EXCEPTION 'predecessor requires correction cycle';END IF;
 IF TG_OP='UPDATE' THEN
  IF(NEW.calculation_mode,NEW.predecessor_review_id) IS DISTINCT FROM(OLD.calculation_mode,OLD.predecessor_review_id) THEN RAISE EXCEPTION 'employee mode/correction identity is immutable';END IF;
  IF NEW.current_input_revision_id IS DISTINCT FROM OLD.current_input_revision_id THEN
   SELECT * INTO r FROM hr_performance_channel_input_revision WHERE(id,tenant_id,park_id,cycle_employee_id)=(NEW.current_input_revision_id,NEW.tenant_id,NEW.park_id,NEW.id);
   IF r.id IS NULL OR r.previous_revision_id IS DISTINCT FROM OLD.current_input_revision_id THEN RAISE EXCEPTION 'invalid input successor';END IF;
  END IF;
 END IF;RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION hr_performance_channel_input_revision_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE ce record;cycle_row record;previous record;c record;old_cell jsonb;p jsonb;role_name text;permission_name text;actor record;changed integer:=0;source_r public.hr_performance_source_activation_receipt%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'channel input revisions are append-only';END IF;
 IF NEW.created_at<transaction_timestamp()-interval '30 seconds' OR NEW.created_at>clock_timestamp()+interval '1 second' THEN RAISE EXCEPTION 'input revision time must be current';END IF;
 SELECT cycle_id INTO ce FROM hr_performance_cycle_employee WHERE(id,tenant_id,park_id)=(NEW.cycle_employee_id,NEW.tenant_id,NEW.park_id);
 SELECT * INTO cycle_row FROM hr_performance_review_cycle WHERE(id,tenant_id,park_id)=(ce.cycle_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 SELECT * INTO ce FROM hr_performance_cycle_employee WHERE(id,tenant_id,park_id)=(NEW.cycle_employee_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 IF ce.id IS NULL OR ce.calculation_mode<>'five_channel_v1' OR ce.status NOT IN('self_review','manager_review','calibration','appealed') OR ce.current_input_revision_id IS DISTINCT FROM NEW.previous_revision_id OR NOT hr_performance_channel_input_valid(NEW.input,cycle_row.template_snapshot->'channelWorkflow') THEN RAISE EXCEPTION 'invalid or stale channel input revision';END IF;
 IF NEW.source_activation_receipt_id IS NOT NULL THEN
 SELECT * INTO source_r FROM public.hr_performance_source_activation_receipt WHERE(id,tenant_id,park_id)=(NEW.source_activation_receipt_id,NEW.tenant_id,NEW.park_id);
 IF source_r.id IS NULL OR source_r.created_xid IS DISTINCT FROM pg_current_xact_id() OR source_r.mode<>'qualified_source' OR cycle_row.source_activation_receipt_id IS DISTINCT FROM source_r.id OR source_r.review_id<>NEW.cycle_employee_id OR source_r.baseline_revision_id<>NEW.id OR NEW.previous_revision_id IS DISTINCT FROM source_r.initial_revision_id OR NEW.revision_no<>2 OR ce.current_input_revision_id IS DISTINCT FROM source_r.initial_revision_id OR ce.status<>'self_review' OR NEW.created_by IS DISTINCT FROM source_r.created_by OR NEW.created_at IS DISTINCT FROM source_r.created_at OR NEW.input IS DISTINCT FROM public.hr_performance_source_activation_expected_input(source_r.id) OR EXISTS(SELECT 1 FROM public.hr_performance_review_action WHERE cycle_employee_id=ce.id) OR NOT public.hr_performance_channel_workflow_valid(cycle_row.template_snapshot->'channelWorkflow',cycle_row.template_snapshot->'channelDefinition',true) OR NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage') OR NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance_template:manage') THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_BASELINE_INVALID';END IF;
 IF NEW.input->'master'->'salaryReference'->>'state'='VALUE' AND NOT(public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:read') AND public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage') AND public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:compensation:manage')) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_SALARY_REQUIRED';END IF;
 RETURN NEW;
 END IF;
 SELECT e.* INTO actor FROM hr_employee e WHERE e.tenant_id=NEW.tenant_id AND e.park_id=NEW.park_id AND e.user_id=NEW.created_by AND NOT e.is_deleted ORDER BY e.id LIMIT 1;
 IF NEW.previous_revision_id IS NULL THEN
  IF NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage') THEN RAISE EXCEPTION 'initial input requires cycle management';END IF;
  IF NEW.revision_no<>1 OR EXISTS(SELECT 1 FROM hr_performance_channel_cells(NEW.input) WHERE cell->>'state'<>'UNPROVIDED') THEN RAISE EXCEPTION 'initial input must be unprovided';END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO previous FROM hr_performance_channel_input_revision WHERE(id,tenant_id,park_id,cycle_employee_id)=(NEW.previous_revision_id,NEW.tenant_id,NEW.park_id,NEW.cycle_employee_id);
 IF previous.id IS NULL OR NEW.revision_no<>previous.revision_no+1 THEN RAISE EXCEPTION 'invalid input predecessor';END IF;
 FOR c IN SELECT * FROM hr_performance_channel_cells(NEW.input) LOOP
  SELECT cell INTO old_cell FROM hr_performance_channel_cells(previous.input) prior_cell WHERE prior_cell.detail_id IS NOT DISTINCT FROM c.detail_id AND prior_cell.field=c.field;
  IF c.cell IS NOT DISTINCT FROM old_cell THEN CONTINUE;END IF;changed:=changed+1;
  p:=hr_performance_channel_policy_for(cycle_row.template_snapshot->'channelDefinition',cycle_row.template_snapshot->'channelWorkflow',c.field);
  IF c.cell->>'state'='UNPROVIDED' OR c.cell->>'actorUserId' IS DISTINCT FROM NEW.created_by::text OR (c.cell->>'changedAt')::timestamptz IS DISTINCT FROM NEW.created_at OR (c.cell->>'state'='EXPLICIT_NULL' AND (p->'required'='true'::jsonb OR p->'allowExplicitNull' IS DISTINCT FROM 'true'::jsonb)) THEN RAISE EXCEPTION 'invalid input author or NULL policy';END IF;
  IF ce.status='appealed' THEN
   IF cycle_row.template_snapshot->'channelWorkflow'->'appealReviewAllowed'->c.field IS DISTINCT FROM 'true'::jsonb OR EXISTS(SELECT 1 FROM hr_employee e WHERE(e.id,e.tenant_id,e.park_id)=(ce.employee_id,ce.tenant_id,ce.park_id) AND e.user_id=NEW.created_by) OR NOT EXISTS(SELECT 1 FROM hr_performance_appeal a WHERE(a.cycle_employee_id,a.tenant_id,a.park_id)=(ce.id,ce.tenant_id,ce.park_id) AND a.status='submitted') THEN RAISE EXCEPTION 'appeal field amendment is not allowed';END IF;
  ELSE
   role_name:=CASE ce.status WHEN 'self_review' THEN 'self' WHEN 'manager_review' THEN 'manager' WHEN 'calibration' THEN 'calibrator' END;
   IF p->>'stage' IS DISTINCT FROM ce.status OR NOT p->'allowedActors' ? role_name THEN RAISE EXCEPTION 'field is outside its stage';END IF;
   IF role_name='self' AND actor.id IS DISTINCT FROM ce.employee_id THEN RAISE EXCEPTION 'self field actor mismatch';END IF;
   IF role_name='manager' AND (actor.id=ce.employee_id OR NOT EXISTS(SELECT 1 FROM hr_employee e WHERE(e.id,e.tenant_id,e.park_id)=(ce.employee_id,ce.tenant_id,ce.park_id) AND e.manager_employee_id=actor.id)) THEN RAISE EXCEPTION 'manager field actor mismatch';END IF;
   IF role_name='calibrator' AND (actor.id=ce.employee_id OR NOT EXISTS(SELECT 1 FROM hr_performance_calibration_batch b JOIN hr_performance_calibration_participant p ON(p.batch_id,p.tenant_id,p.park_id)=(b.id,b.tenant_id,b.park_id) WHERE(b.cycle_id,b.tenant_id,b.park_id)=(ce.cycle_id,ce.tenant_id,ce.park_id) AND b.status='active' AND p.participant_user_id=NEW.created_by)) THEN RAISE EXCEPTION 'calibration field actor mismatch';END IF;
  END IF;
  permission_name:=CASE ce.status WHEN 'self_review' THEN 'hr:performance:self_review' WHEN 'manager_review' THEN 'hr:performance:manager_review' WHEN 'calibration' THEN 'hr:performance:calibrate' WHEN 'appealed' THEN 'hr:performance:appeal_review' END;
  IF NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,permission_name) THEN RAISE EXCEPTION 'current performance field permission required';END IF;
  IF c.field='salaryReference' AND NOT(hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:read') AND hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage') AND hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:compensation:manage')) THEN RAISE EXCEPTION 'salary reference authority required';END IF;
 END LOOP;
 IF changed=0 THEN RAISE EXCEPTION 'input amendment is empty';END IF;RETURN NEW;
END $$;

CREATE FUNCTION hr_performance_source_activation_derive_definition(content jsonb,mapping jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
WITH facts AS(SELECT f FROM jsonb_array_elements(content->'facts') f),profile AS(SELECT f->'values' v FROM facts WHERE f->>'family'='template_profile' AND f->'identitySha256'=mapping->'profileIdentitySha256'),policy AS(SELECT '{"businessName":null,"stage":null,"allowedActors":[],"required":null,"allowExplicitNull":null}'::jsonb p),
items AS(SELECT m map,f->'values' v FROM jsonb_array_elements(mapping->'items') m JOIN facts ON f->>'family'='dimension_profile' AND f->'identitySha256'=m->'sourceIdentitySha256'),
guides AS(SELECT m map,f->'values' v FROM jsonb_array_elements(mapping->'guides') m JOIN facts ON f->>'family'='dimension_level_guide' AND f->'identitySha256'=m->'sourceIdentitySha256'),
grades AS(SELECT m map,f->'values' v FROM jsonb_array_elements(mapping->'grades') m JOIN facts ON f->>'family'='level_rule' AND f->'identitySha256'=m->'sourceIdentitySha256')
SELECT jsonb_build_object('schemaVersion',1,'displayName',v->'source_assessment_name','departmentLabel',v->'source_department','weights',jsonb_build_object('sPercent',v->'source_s_percent','mPercent',v->'source_m_percent','tPercent',v->'source_t_percent','xPercent',v->'source_x_percent','cPercent',v->'source_c_percent'),'channels',(SELECT jsonb_object_agg(k,policy.p) FROM unnest(ARRAY['s','m','t','x','c'])k CROSS JOIN policy),'adjustmentPolicy',(SELECT jsonb_object_agg(k,policy.p||jsonb_build_object('sourceSwitch',v->('source_'||k),'inputMode',NULL)) FROM unnest(ARRAY['master','timekeep','bonus'])k CROSS JOIN policy),
'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',i.map->'itemId','name',i.v->'source_item_name','fullValue',i.v->'source_full_value','order',(i.v->>'source_my_order')::int,'sourceAssessmentRef',i.v->'source_assessment_id','guides',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',g.map->'guideId','grade',g.v->'source_grade','description',g.v->'source_description','minValue',g.v->'source_min_value','maxValue',g.v->'source_max_value','order',(g.v->>'source_my_order')::int) ORDER BY g.map->>'sourceIdentitySha256' COLLATE "C") FROM guides g WHERE g.map->'itemId'=i.map->'itemId'),'[]'::jsonb)) ORDER BY i.map->>'sourceIdentitySha256' COLLATE "C") FROM items i),'[]'::jsonb),
'gradeCandidates',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',map->'gradeId','code',v->'source_ass_grade','description',v->'source_description','sourceOrderText',v->'source_my_order','sourceAssessmentRef',v->'source_assessment_id','minValue',v->'source_min_value','maxValue',v->'source_max_value') ORDER BY map->>'sourceIdentitySha256' COLLATE "C") FROM grades),'[]'::jsonb)) FROM profile
$$;
CREATE FUNCTION hr_performance_source_activation_differences(t varchar,p varchar,draft uuid,revision uuid,profile_identity text) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $$
WITH selected AS(SELECT r.snapshot,m.content FROM public.hr_performance_source_draft_revision r JOIN public.hr_performance_source_manifest m ON m.id=r.manifest_id WHERE(r.id,r.tenant_id,r.park_id,r.draft_id)=(revision,t,p,draft)),
proposal AS(SELECT public.hr_performance_source_activation_derive_definition(s.content,public.hr_performance_source_activation_mapping(t,p,draft,revision,profile_identity,false)) value FROM selected s),
changes AS(SELECT jsonb_build_object('family',a->'family','sourceFactId',a->'sourceFactId','field',kv.key,'originalValue',o->'values'->kv.key,'currentValue',kv.value) value FROM selected s CROSS JOIN LATERAL jsonb_array_elements(s.snapshot->'records')a JOIN LATERAL jsonb_array_elements(s.content->'facts')o ON(o->'family',o->'sourceFactId')=(a->'family',a->'sourceFactId') CROSS JOIN LATERAL jsonb_each(a->'values')kv WHERE a->>'family' IN('dimension_result','master_result') AND kv.key IN('source_self_value','source_m_item_value','source_item_value','source_x_item_value','source_c_item_value','source_appraisal','source_master_value','source_timekeep_value','source_bonus_value','source_self_appraisal','source_description','source_pay') AND kv.value IS DISTINCT FROM o->'values'->kv.key),
definition_fields AS(SELECT COALESCE(jsonb_agg('definition.'||kv.key ORDER BY kv.key COLLATE "C"),'[]'::jsonb) fields FROM selected s,proposal p CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(s.snapshot->'definition')='object' THEN s.snapshot->'definition' ELSE '{}'::jsonb END)kv WHERE kv.value IS DISTINCT FROM p.value->kv.key),
pending AS(SELECT COALESCE(jsonb_agg(value ORDER BY value->>'family' COLLATE "C",value->>'sourceFactId' COLLATE "C",value->>'field' COLLATE "C"),'[]'::jsonb) changes FROM changes),
result AS(SELECT jsonb_build_object('sha256',encode(sha256(convert_to(f.fields::text,'UTF8')),'hex'),'count',jsonb_array_length(f.fields),'fields',f.fields) definition,jsonb_build_object('sha256',encode(sha256(convert_to(p.changes::text,'UTF8')),'hex'),'count',jsonb_array_length(p.changes),'changes',p.changes) pending,s.snapshot FROM definition_fields f,pending p,selected s)
SELECT jsonb_build_object('definitionDifference',definition,'pendingInputDifference',pending,'differenceSha256',encode(sha256(convert_to(jsonb_build_object('definitionDifference',definition,'pendingInputDifference',pending,'configuredDefinition',snapshot->'definition','configuredWorkflow',snapshot->'workflow')::text,'UTF8')),'hex')) FROM result
$$;
CREATE FUNCTION hr_performance_source_activation_text_valid(v jsonb,min_length integer,max_length integer) RETURNS boolean LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT COALESCE(jsonb_typeof(v)='string' AND length(v#>>'{}') BETWEEN min_length AND max_length AND length(btrim(v#>>'{}',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'))>=min_length,false)
$$;
CREATE FUNCTION hr_performance_source_activation_request_valid(r jsonb,kind text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE k text;target jsonb;
BEGIN
 IF NOT public.hr_performance_channel_object_v1(r,ARRAY['expectedRevisionId','expectedManifestSha256','expectedQualificationSha256','target','reason','acknowledgedDifferenceSha256']||CASE WHEN kind='review' THEN ARRAY['mode','cycleCode','cycleName'] ELSE ARRAY[]::text[] END) THEN RETURN false;END IF;
 FOR k IN SELECT unnest(ARRAY['expectedRevisionId','expectedManifestSha256','expectedQualificationSha256','reason','acknowledgedDifferenceSha256']||CASE WHEN kind='review' THEN ARRAY['mode','cycleCode','cycleName'] ELSE ARRAY[]::text[] END) LOOP IF jsonb_typeof(r->k)<>'string' THEN RETURN false;END IF;END LOOP;
 IF r->>'expectedRevisionId' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' OR r->>'expectedManifestSha256' !~ '^[0-9a-f]{64}$' OR r->>'expectedQualificationSha256' !~ '^[0-9a-f]{64}$' OR r->>'acknowledgedDifferenceSha256' !~ '^[0-9a-f]{64}$' OR NOT public.hr_performance_source_activation_text_valid(r->'reason',2,2000) THEN RETURN false;END IF;
 target:=r->'target';IF target->>'mode'='new' THEN
 IF NOT public.hr_performance_channel_object_v1(target,ARRAY['mode','templateCode','templateName','versionName']) THEN RETURN false;END IF;
 FOR k IN SELECT unnest(ARRAY['templateCode','templateName','versionName']) LOOP IF NOT public.hr_performance_source_activation_text_valid(target->k,1,CASE k WHEN 'templateCode' THEN 64 ELSE 120 END) THEN RETURN false;END IF;END LOOP;
 ELSIF target->>'mode'='new_version' THEN
 IF NOT public.hr_performance_channel_object_v1(target,ARRAY['mode','templateId','expectedVersionId','expectedDefinitionRevisionId','expectedWorkflowRevisionId','versionName']) OR NOT public.hr_performance_source_activation_text_valid(target->'versionName',1,120) THEN RETURN false;END IF;
 FOR k IN SELECT unnest(ARRAY['templateId','expectedVersionId','expectedDefinitionRevisionId','expectedWorkflowRevisionId']) LOOP IF k='expectedWorkflowRevisionId' AND target->k='null'::jsonb THEN CONTINUE;END IF;IF jsonb_typeof(target->k)<>'string' OR target->>k !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN RETURN false;END IF;END LOOP;
 ELSE RETURN false;END IF;
 IF kind='review' AND(r->>'mode' NOT IN('qualified_source','manual_current') OR NOT public.hr_performance_source_activation_text_valid(r->'cycleCode',1,64) OR NOT public.hr_performance_source_activation_text_valid(r->'cycleName',1,120)) THEN RETURN false;END IF;RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE FUNCTION hr_performance_source_activation_receipt_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE d record;r record;m record;q jsonb;expected_mapping jsonb;diff jsonb;v record;parent record;input jsonb;c record;policy jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_RECEIPT_IMMUTABLE';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.tenant_id||':'||NEW.park_id||':'||NEW.kind||':'||NEW.source_identity_sha256,0));
 SELECT * INTO d FROM public.hr_performance_source_draft WHERE(id,tenant_id,park_id)=(NEW.draft_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 SELECT * INTO r FROM public.hr_performance_source_draft_revision WHERE(id,tenant_id,park_id,draft_id)=(NEW.draft_revision_id,NEW.tenant_id,NEW.park_id,NEW.draft_id);
 SELECT * INTO m FROM public.hr_performance_source_manifest WHERE(id,tenant_id,park_id)=(NEW.manifest_id,NEW.tenant_id,NEW.park_id);
 IF d.id IS NULL OR r.id IS NULL OR m.id IS NULL OR d.kind IS DISTINCT FROM NEW.kind OR d.current_revision_id IS DISTINCT FROM r.id OR r.manifest_id IS DISTINCT FROM m.id OR r.source_fact_id IS DISTINCT FROM NEW.source_fact_id OR d.source_identity_sha256 IS DISTINCT FROM NEW.source_identity_sha256 OR NEW.binding IS DISTINCT FROM r.snapshot->'binding' OR NEW.created_xid IS DISTINCT FROM pg_current_xact_id() OR NEW.created_at IS DISTINCT FROM transaction_timestamp() THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_IDENTITY_INVALID';END IF;
 IF NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance_template:manage') OR(NEW.kind='review' AND NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage')) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_PERMISSION_REQUIRED';END IF;
 q:=public.hr_performance_source_activation_qualification(NEW.tenant_id,NEW.park_id,NEW.created_by,d.id,r.id);
 IF q IS NULL OR q IS DISTINCT FROM NEW.qualification OR q->>'qualificationHash' IS DISTINCT FROM NEW.qualification_sha256 OR q->'gates'->'SOURCE_GENERATION' IS DISTINCT FROM 'true'::jsonb OR(NEW.mode='qualified_source' AND q->'sourceQualified' IS DISTINCT FROM 'true'::jsonb) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_QUALIFICATION_CHANGED';END IF;
 IF NOT public.hr_performance_source_activation_request_valid(NEW.request,NEW.kind) OR NEW.request->>'expectedRevisionId' IS DISTINCT FROM r.id::text OR NEW.request->>'expectedManifestSha256' IS DISTINCT FROM m.manifest_sha256 OR NEW.request->>'expectedQualificationSha256' IS DISTINCT FROM NEW.qualification_sha256 OR NEW.request->>'reason' IS DISTINCT FROM NEW.reason OR(NEW.kind='review' AND NEW.request->>'mode' IS DISTINCT FROM NEW.mode) OR NEW.request_sha256 IS DISTINCT FROM encode(sha256(convert_to(jsonb_build_object('route',CASE NEW.kind WHEN 'template' THEN 'activate-template' ELSE 'activate-review' END,'draftRevisionId',r.id,'body',NEW.request)::text,'UTF8')),'hex') OR NEW.business_key_sha256 IS DISTINCT FROM encode(sha256(convert_to(jsonb_build_object('kind',NEW.kind,'sourceIdentitySha256',NEW.source_identity_sha256,'predecessorReceiptId',NULL)::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_REQUEST_INVALID';END IF;
 expected_mapping:=public.hr_performance_source_activation_mapping(NEW.tenant_id,NEW.park_id,d.id,r.id,q->>'profileIdentitySha256',NEW.mode='manual_current');
 IF expected_mapping IS NULL OR expected_mapping IS DISTINCT FROM NEW.mapping OR NOT public.hr_performance_source_activation_mapping_config_valid(NEW.mapping,r.snapshot->'definition',r.snapshot->'workflow',NEW.mode='qualified_source') OR(NEW.kind='review' AND NOT public.hr_performance_channel_workflow_valid(r.snapshot->'workflow',r.snapshot->'definition',true)) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_MAPPING_INVALID';END IF;
 diff:=public.hr_performance_source_activation_differences(NEW.tenant_id,NEW.park_id,d.id,r.id,q->>'profileIdentitySha256');
 IF NEW.definition_difference IS DISTINCT FROM diff->'definitionDifference' OR NEW.pending_input_difference IS DISTINCT FROM diff->'pendingInputDifference' OR NEW.request->>'acknowledgedDifferenceSha256' IS DISTINCT FROM diff->>'differenceSha256' THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_DIFFERENCE_CHANGED';END IF;
 IF EXISTS(SELECT 1 FROM public.hr_performance_template_version WHERE id=NEW.template_version_id) OR EXISTS(SELECT 1 FROM public.hr_performance_channel_definition_revision WHERE id=NEW.definition_revision_id) OR EXISTS(SELECT 1 FROM public.hr_performance_channel_workflow_revision WHERE id=NEW.workflow_revision_id) OR EXISTS(SELECT 1 FROM public.hr_performance_review_cycle WHERE id=NEW.cycle_id) OR EXISTS(SELECT 1 FROM public.hr_performance_cycle_employee WHERE id=NEW.review_id) OR EXISTS(SELECT 1 FROM public.hr_performance_channel_input_revision WHERE id IN(NEW.initial_revision_id,NEW.baseline_revision_id)) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_TARGET_NOT_FRESH';END IF;
 IF NEW.request->'target'->>'mode'='new' THEN
  IF EXISTS(SELECT 1 FROM public.hr_performance_template WHERE id=NEW.template_id) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_TARGET_NOT_FRESH';END IF;
 ELSE
  SELECT * INTO parent FROM public.hr_performance_template WHERE(id,tenant_id,park_id)=(NEW.template_id,NEW.tenant_id,NEW.park_id) AND NOT is_deleted FOR UPDATE;
  SELECT * INTO v FROM public.hr_performance_template_version WHERE(template_id,tenant_id,park_id,version_no)=(parent.id,NEW.tenant_id,NEW.park_id,parent.current_version_no) FOR UPDATE;
  IF parent.id IS NULL OR parent.status='retired' OR NEW.request->'target'->>'templateId' IS DISTINCT FROM parent.id::text OR NEW.request->'target'->>'expectedVersionId' IS DISTINCT FROM v.id::text OR NEW.request->'target'->>'expectedDefinitionRevisionId' IS DISTINCT FROM v.channel_definition_revision_id::text OR NEW.request->'target'->>'expectedWorkflowRevisionId' IS DISTINCT FROM v.channel_workflow_revision_id::text THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_TARGET_CHANGED';END IF;
 END IF;
 IF (r.snapshot->'workflow' IS NULL OR r.snapshot->'workflow'='null'::jsonb) IS DISTINCT FROM (NEW.workflow_revision_id IS NULL) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_WORKFLOW_ID_INVALID';END IF;
 IF NEW.kind='review' THEN
  IF NEW.binding->>'employeeId' IS DISTINCT FROM NEW.employee_id::text OR NOT EXISTS(SELECT 1 FROM public.hr_employee e JOIN public.sys_org o ON(o.id,o.tenant_id,o.park_id)=(e.primary_org_id,e.tenant_id,e.park_id) WHERE(e.id,e.tenant_id,e.park_id)=(NEW.employee_id,NEW.tenant_id,NEW.park_id) AND NOT e.is_deleted AND e.employment_status<>'departed' AND NOT o.is_deleted AND o.status='enabled' AND o.id::text=NEW.binding->>'orgId') OR NEW.binding->>'startDate' IS NULL OR NEW.binding->>'endDate' IS NULL OR (NEW.binding->>'startDate')::date>(NEW.binding->>'endDate')::date OR length(btrim(NEW.binding->>'businessPeriodRef')) IS NULL OR length(btrim(NEW.binding->>'businessPeriodRef'))=0 OR(NEW.mode='qualified_source' AND q->>'resolvedEmployeeId' IS DISTINCT FROM NEW.employee_id::text) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_BINDING_INVALID';END IF;
 END IF;
 IF NEW.mode='qualified_source' THEN
  input:=public.hr_performance_source_activation_build_input(m.content,r.snapshot->'workflow',NEW.mapping,NEW.source_fact_id,NEW.created_by,NEW.created_at,NEW.id);
  IF NOT public.hr_performance_channel_input_valid(input,r.snapshot->'workflow') THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_SOURCE_POLICY_TEXT_CONFLICT';END IF;
  IF NOT(r.snapshot->'workflow' ? 'detailAppraisalPolicy') AND EXISTS(SELECT 1 FROM jsonb_array_elements(m.content->'facts')f WHERE f->>'family'='dimension_result' AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.mapping->'details') detail WHERE detail->'sourceIdentitySha256'=f->'identitySha256') AND f->'values'->'source_appraisal'<>'null'::jsonb) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_APPRAISAL_POLICY_REQUIRED';END IF;
  FOR c IN SELECT * FROM public.hr_performance_channel_cells(input) LOOP policy:=public.hr_performance_channel_policy_for(r.snapshot->'definition',r.snapshot->'workflow',c.field);IF c.cell->>'state'='VALUE' AND policy->'required'='true'::jsonb AND c.field IN('detailAppraisal','selfAppraisal','appraisal','description') AND length(btrim(c.cell->>'value'))=0 THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_SOURCE_POLICY_TEXT_CONFLICT';END IF;END LOOP;
  IF input->'master'->'salaryReference'->>'state'='VALUE' AND NOT(public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:read') AND public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:compensation:manage')) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_SALARY_REQUIRED';END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_hr_source_activation_receipt BEFORE INSERT OR UPDATE OR DELETE ON hr_performance_source_activation_receipt FOR EACH ROW EXECUTE FUNCTION hr_performance_source_activation_receipt_guard();
CREATE FUNCTION hr_performance_source_activation_final_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
DECLARE r public.hr_performance_source_activation_receipt%ROWTYPE;d record;v record;c record;e record;i record;b record;q jsonb;parent record;
BEGIN
 SELECT * INTO r FROM public.hr_performance_source_activation_receipt WHERE id=NEW.id;
 SELECT * INTO d FROM public.hr_performance_source_draft_revision WHERE id=r.draft_revision_id;
 SELECT * INTO v FROM public.hr_performance_template_version WHERE(id,tenant_id,park_id)=(r.template_version_id,r.tenant_id,r.park_id);
 SELECT * INTO parent FROM public.hr_performance_template WHERE(id,tenant_id,park_id)=(r.template_id,r.tenant_id,r.park_id);
 IF parent.id IS NULL OR parent.is_deleted OR parent.current_version_no IS DISTINCT FROM v.version_no OR v.version_name IS DISTINCT FROM r.request->'target'->>'versionName' OR v.create_by IS DISTINCT FROM r.created_by OR v.create_time IS DISTINCT FROM r.created_at OR(r.request->'target'->>'mode'='new' AND(parent.template_code IS DISTINCT FROM r.request->'target'->>'templateCode' OR parent.template_name IS DISTINCT FROM r.request->'target'->>'templateName' OR parent.create_by IS DISTINCT FROM r.created_by OR parent.create_time IS DISTINCT FROM r.created_at)) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_FINAL_TARGET_INVALID';END IF;
 IF r.created_xid IS DISTINCT FROM pg_current_xact_id() OR v.id IS NULL OR v.template_id<>r.template_id OR v.calculation_mode<>'five_channel_v1' OR v.channel_definition_revision_id IS DISTINCT FROM r.definition_revision_id OR v.channel_workflow_revision_id IS DISTINCT FROM r.workflow_revision_id OR NOT EXISTS(SELECT 1 FROM public.hr_performance_channel_definition_revision x WHERE x.id=r.definition_revision_id AND x.config=d.snapshot->'definition' AND x.revision_no=1 AND x.previous_revision_id IS NULL AND x.created_by=r.created_by AND x.created_at=r.created_at) OR(r.workflow_revision_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_performance_channel_workflow_revision x WHERE x.id=r.workflow_revision_id AND x.policy=d.snapshot->'workflow' AND x.definition_revision_id=r.definition_revision_id AND x.revision_no=1 AND x.previous_revision_id IS NULL AND x.created_by=r.created_by AND x.created_at=r.created_at)) OR v.status IS DISTINCT FROM (CASE r.kind WHEN 'template' THEN 'draft' ELSE 'published' END) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_FINAL_TEMPLATE_INVALID';END IF;
 IF r.kind='review' THEN
  SELECT * INTO c FROM public.hr_performance_review_cycle WHERE(id,tenant_id,park_id)=(r.cycle_id,r.tenant_id,r.park_id) FOR UPDATE;
  SELECT * INTO e FROM public.hr_performance_cycle_employee WHERE(id,tenant_id,park_id)=(r.review_id,r.tenant_id,r.park_id) FOR UPDATE;
  SELECT * INTO i FROM public.hr_performance_channel_input_revision WHERE id=r.initial_revision_id;
  SELECT * INTO b FROM public.hr_performance_channel_input_revision WHERE id=r.baseline_revision_id;
  IF c.id IS NULL OR e.id IS NULL OR c.source_activation_receipt_id IS DISTINCT FROM r.id OR c.status<>'self_review' OR e.cycle_id<>c.id OR e.employee_id<>r.employee_id OR e.status<>'self_review' OR e.create_time IS DISTINCT FROM r.created_at OR e.predecessor_review_id IS NOT NULL OR e.current_input_revision_id IS DISTINCT FROM COALESCE(r.baseline_revision_id,r.initial_revision_id) OR num_nonnulls(e.self_score,e.manager_score,e.calibrated_score,e.final_score,e.final_level_code,e.result_finalized_at,e.confirmed_at,e.final_input_revision_id)>0 OR(SELECT count(*) FROM public.hr_performance_cycle_employee WHERE cycle_id=c.id)<>1 OR(SELECT count(*) FROM public.hr_performance_channel_input_revision WHERE cycle_employee_id=e.id)<>(CASE r.mode WHEN 'qualified_source' THEN 2 ELSE 1 END) OR i.id IS NULL OR i.revision_no<>1 OR i.previous_revision_id IS NOT NULL OR i.created_by<>r.created_by OR i.created_at<>r.created_at OR i.source_activation_receipt_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.hr_performance_channel_cells(i.input) WHERE cell->>'state'<>'UNPROVIDED') OR(r.mode='qualified_source' AND(b.id IS NULL OR b.source_activation_receipt_id IS DISTINCT FROM r.id OR b.revision_no<>2 OR b.previous_revision_id IS DISTINCT FROM i.id OR b.input IS DISTINCT FROM public.hr_performance_source_activation_expected_input(r.id))) OR EXISTS(SELECT 1 FROM public.hr_performance_review_action WHERE cycle_employee_id=e.id) OR EXISTS(SELECT 1 FROM public.hr_performance_review_submission WHERE cycle_employee_id=e.id) OR EXISTS(SELECT 1 FROM public.hr_performance_calibration_batch WHERE cycle_id=c.id) OR EXISTS(SELECT 1 FROM public.hr_performance_appeal WHERE cycle_employee_id=e.id) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_FINAL_REVIEW_INVALID';END IF;
 END IF;
 q:=public.hr_performance_source_activation_qualification(r.tenant_id,r.park_id,r.created_by,r.draft_id,r.draft_revision_id);
 IF q IS DISTINCT FROM r.qualification OR q->'gates'->'SOURCE_GENERATION' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_FINAL_GENERATION_CHANGED';END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER trg_hr_source_activation_final AFTER INSERT ON hr_performance_source_activation_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION hr_performance_source_activation_final_guard();
COMMIT;
